import React from "react";
import JobItem from "./JobItem";

const JobList = ({ jobs, refreshJobs }) => {
  return (
    <div className="job-list">
      {jobs.length === 0 ? (
        <p>No jobs added yet.</p>
      ) : (
        jobs.map((job) => (
          <JobItem key={job._id} job={job} refreshJobs={refreshJobs} />
        ))
      )}
    </div>
  );
};

export default JobList;
